#' Join an election info and an election result table.
#'
#' @description
#' This function takes a parsed election info table and a parsed election
#' result table and joins the two tables.
#'
#' @param info_tbl An object, generated by parsing an election info file using
#' the `parse_eCH_0252_elections_info` function.
#' @param result_tbl An object, generated by parsing an election info file using
#' the `parse_eCH_0252_elections_result` function.
#'
#' @return A dataframe.
#'
#' @export
#'
#' @examples
#' \dontrun{
#'
#'
#' }
#'
join_eCH_0252_infos_results <- function(info_tbl, result_tbl){


  # PROPORTIONAL ===============================================================


  if ("list_listIdentification" %in% names(info_tbl)) {

    # Prepare result data for join
    result <- result_tbl |>
      dplyr::rename_with(~gsub("candidateResults", "candidate", .x)) |>
      dplyr::rename(
        "candidate_candidateReference" = "candidate_candidateReferenceOnPosition",
        "list_listIdentification" = "listIdentification",
        "list_listIndentureNumber" = "listIndentureNumber"
      ) |>
      dplyr::distinct()

    # Prepare infor data for join
    info <- info_tbl |>
      dplyr::rename_with(~gsub("candidatePosition", "candidate", .x)) |>
      dplyr::filter(list_isEmptyList == "false")

    # Join info and result data (set many-to-many for cases with multiple counting circles)
    data <- info |>
      dplyr::left_join(result, relationship = "many-to-many")


    # MAJORITY =================================================================


  } else {

    # Prepare write in result table
    if (any(grepl("candidate_familyName", names(result_tbl)))) {

      # Split into regular and write in candidate results
      result_regular <- result_tbl |>
        dplyr::filter(is.na(candidate_familyName)) |>
        dplyr::select(dplyr::where(~!all(is.na(.x))))

      result_writein <- result_tbl |>
        dplyr::filter(!is.na(candidate_familyName)) |>
        dplyr::select(dplyr::where(~!all(is.na(.x))))

      # Define joining variables
      join_vars <- c("cantonId", "pollingDay", "electionGroupIdentification", "electionIdentification")

      # Define variables to drop before the join
      drop_vars <- intersect(names(result_writein), names(info_tbl)) |>
        setdiff(join_vars)

      # Prepare join file
      join_data <- info_tbl |>
        dplyr::select(
          -all_of(drop_vars),
          -cand_list_id
        ) |>
        dplyr::distinct()

      # Add info columns to writein object by joining the two tables (except the common vars to drop)
      data_writein <- result_writein |>
        dplyr::left_join(join_data, by = join_vars)

    } else {

      result_regular <- result_tbl

    }

    # Join info and regular result data
    data_regular <- info_tbl |>
      dplyr::left_join(result_regular)

    # Add write in results
    if (any(grepl("candidate_familyName", names(result_tbl)))) {
      data <- data_regular |>
        dplyr::bind_rows(data_writein)
    } else {
      data <- data_regular
    }
  }

  return(data)

}
